'use strict';
(function(root){
const E=root.HZLPlanningEngine,D=root.HZLEventData;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(v,d=0)=>Number(v).toLocaleString('en-IN',{maximumFractionDigits:d});
const table=(h,rows)=>`<div class="table-wrap"><table><thead><tr>${h.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const card=(t,s,b)=>`<section class="card"><div class="card-head"><div><h2>${esc(t)}</h2><p>${esc(s)}</p></div></div>${b}</section>`;
let host=null,metal='Zinc',draft=null,review=null,message='',pending=null;
const applied={},audit=[];
function log(action,detail){audit.push({sequence:audit.length+1,at:new Date().toISOString(),action,metal,...detail});}
function blank(ctx){const c=D.cases.find(c=>c.metals.includes(ctx.metal)&&c.published<=ctx.asOf);return {title:c?.title||'Commercial sensitivity',source:c?.source||'',url:c?.url||'',published:c?.published||ctx.asOf,geography:'India domestic demand; validate actual customer and trade-route exposure',rationale:'Hypothetical sensitivity for discussion; historical evidence does not establish a numerical forecast effect.',metal:ctx.metal,months:ctx.rows.map(r=>r.month),exposure:100,profile:[1,.75,.5],cargoOrigin:'All',changes:E.defaults(),reviewer:''};}
function context(){return host.context(metal);}
function sync(){const ctx=context();if(!draft||draft.metal!==metal||JSON.stringify(draft.months)!==JSON.stringify(ctx.rows.map(r=>r.month))){draft=blank(ctx);review=null;}return ctx;}
function active(ctx){const record=applied[ctx.metal];if(!record||record.invalidated)return null;if(record.fingerprint!==E.fingerprint(ctx)){record.invalidated=true;record.suspendedAt=new Date().toISOString();log('Suspended after baseline change',{metal:ctx.metal,title:record.scenario.title});return null;}return record;}
function outcome(ctx){const a=active(ctx);return E.calculate(ctx,a?.scenario);}
function banner(ctx){const a=active(ctx),old=applied[ctx.metal];return `<div class="planning-banner"><div><strong>${a?'Reviewed scenario applied':old?'Baseline changed · scenario needs review':'Baseline planning view'}</strong><p>${a?esc(a.scenario.title)+' · '+esc(a.reviewer)+' · demand, premium, parity, ETAs and allocation share this scenario.':old?'Previous scenario is suspended for this baseline or horizon. Review again before applying it.':'No event sensitivity is applied. Review a scenario to compare its commercial effect.'}</p></div><button class="secondary" data-page="planning">${a?'Review effects':'Open connected planning'} →</button></div>`;}
function field(key,label,value,attrs=''){return `<div class="field"><label for="plan-${key}">${esc(label)}</label><input id="plan-${key}" name="${key}" value="${esc(value)}" ${attrs} required></div>`;}
function evidencePreview(){const c=D.cases.find(c=>c.url===draft.url&&c.title===draft.title);if(!c)return '<p class="mini">Custom source: inspect the original report and verify publication date, product, geography and availability before review.</p>';return `<div class="planning-evidence"><strong>Observed historical evidence · ${esc(c.period)}</strong><p>${esc(c.fact)}</p><p class="mini">${esc(c.limit)}</p><a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">Open original source · published ${esc(c.published)} ↗</a><p class="mini">The numeric sensitivities below are hypothetical assumptions, separate from this evidence.</p></div>`;}
function draftForm(ctx){const unit=ctx.unit==='kg'?'USD/kg':'USD/t';return `<form id="planning-form">${card('1 · Evidence and exposure','Choose a historical example or enter a dated source. Imported records still require review.',`<div class="filter-row"><label for="plan-case">Evidence library</label><select id="plan-case"><option value="">Select a case…</option>${D.cases.filter(c=>c.metals.includes(metal)&&c.published<=ctx.asOf).map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('')}</select><button type="button" class="secondary" data-plan="case">Load case as draft</button></div><div class="form-grid">${field('title','Scenario title',draft.title,'maxlength="160"')}${field('source','Source / publisher',draft.source,'maxlength="160"')}${field('url','Original HTTPS source',draft.url,'type="url" maxlength="2000"')}${field('published','Publication date',draft.published,`type="date" max="${ctx.asOf}"`)}${field('geography','Affected geographies and exposure rationale',draft.geography,'maxlength="500"')}${field('exposure','Share of order forecast exposed (%)',draft.exposure,'type="number" min="0" max="100" step="any"')}</div>${evidencePreview()}<label for="plan-rationale">Why these changes and monthly weights are appropriate</label><textarea id="plan-rationale" name="rationale" required maxlength="1000" rows="3">${esc(draft.rationale)}</textarea>`)}${card('2 · Conditional assumptions','Demand effect = sensitivity × exposed share × monthly weight. Pricing changes use the monthly weight; ETA delay applies only to selected cargo origins.',`<div class="form-grid">${[['demandShock','Order sensitivity (%)',-50,50],['priceShock','Metal reference change (%)',-50,100],['premiumShift','Premium change ('+unit+')',-1000,1000],['freightShift','Freight change ('+unit+')',-1000,1000],['fxShock','FX change (%)',-50,50],['dutyDelta','Duty change (percentage points)',-100,100],['delay','ETA delay (whole days)',0,90]].map(([k,l,min,max])=>field(k,l,draft.changes[k],`type="number" min="${min}" max="${max}" step="${k==='delay'?'1':'any'}"`)).join('')}${draft.profile.map((v,i)=>field('weight'+i,ctx.rows[i].month+' transmission weight',v,'type="number" min="0" max="1" step="any"')).join('')}<div class="field"><label for="plan-origin">Cargo origin affected by delay</label><select id="plan-origin" name="cargoOrigin">${['All',...new Set(ctx.cargo.map(c=>c.origin))].map(o=>`<option ${draft.cargoOrigin===o?'selected':''}>${esc(o)}</option>`).join('')}</select></div>${field('reviewer','Reviewer name (session annotation)',draft.reviewer,'maxlength="100"')}</div><p class="mini">The exposure percentage scales the order forecast only. Cost and price sensitivities are entered separately. Weights are assumptions, not event probabilities. Duty is entered as a change to the baseline rate. No duplicate scenario stacking.</p><button type="submit">Calculate and review impact →</button>`)}</form>`;}
function comparison(r){const max=Math.max(1,...r.rows.flatMap(x=>[x.baselinePoint,x.point]))*1.12;return `<svg class="chart" viewBox="0 0 650 270" role="img" aria-label="Baseline versus conditional order forecast, ${r.unit}">${[0,.5,1].map(v=>`<line x1="62" x2="625" y1="${215-170*v}" y2="${215-170*v}" stroke="#e1e9e4"/><text x="4" y="${219-170*v}">${n(max*v)}</text>`).join('')}${r.rows.map((x,i)=>{const x0=105+i*185;return `<rect x="${x0}" y="${215-x.baselinePoint/max*170}" width="36" height="${x.baselinePoint/max*170}" fill="#176c50"/><rect x="${x0+40}" y="${215-x.point/max*170}" width="36" height="${x.point/max*170}" fill="#be873e"/><text x="${x0+38}" y="246" text-anchor="middle">${x.month}</text>`;}).join('')}</svg><div class="legend"><span><i class="key"></i>Baseline</span><span>■ Conditional scenario · ${r.unit}</span></div>`;}
function impact(r){return `<div class="grid equal">${card('Order outlook','Baseline and conditional forecast on the same monthly horizon',comparison(r))}${card('First-month commercial impact','Conditional sensitivities; not a market quote or an approved auction price',table(['Measure','Baseline','Conditional'],[['Orders ('+r.unit+')',n(r.rows[0].baselinePoint),n(r.rows[0].point)],['Premium (USD/'+r.unit+')',n(r.rows[0].baselinePremium,2),n(r.rows[0].premium,2)],['Import parity (INR/'+r.unit+')',n(r.rows[0].baseParity,2),n(r.rows[0].parity,2)],['Domestic reservation ('+r.unit+')',n(r.rows[0].baseDomestic),n(r.rows[0].domestic)],['Residual export ('+r.unit+')',n(r.rows[0].baseExport),n(r.rows[0].export)]]))}</div>${card('Monthly demand-led allocation','Reserve max(orders, bookings) + buffer, limited by capacity. Residual exports require market-access and netback review.',table(['Month','Base orders','Conditional','Change','Booked','Domestic reserve','Residual export','Unserved'],r.rows.map(x=>[x.month,n(x.baselinePoint),n(x.point),n(x.delta),n(x.booked),n(x.domestic),n(x.export),n(x.unserved)+(x.bookingException?' · bookings exceed forecast':'')])))}${card('Arrivals and auction preparation','ETAs move by calendar days; volumes are rebucketed by actual shifted date. Auction references require a separate commercial decision.',table(['Month','Base arrivals '+r.unit,'Conditional arrivals '+r.unit,'Premium USD/'+r.unit,'Parity INR/'+r.unit,'Auction sensitivity USD/'+r.unit],r.rows.map(x=>[x.month,n(x.baseArrivals),n(x.arrivals),n(x.premium,2),n(x.parity,2),n(x.auctionReference,2)]))+`<p class="mini">${n(r.arrivalsOutsideHorizon)} ${r.unit} of registered cargo falls outside this horizon after the delay. Auction sensitivity = editable starting premium + assumed premium change; it is not a clearing-price prediction.</p>`+table(['Cargo','Origin','Quantity '+r.unit,'Baseline ETA','Conditional ETA'],r.shipments.map(c=>[esc(c.id),esc(c.origin),n(c.quantity),c.baselineEta,c.scenarioEta])))}`;}
function render(ctx){const first=!host;host=ctx;if(first&&!pending)metal=ctx.selectedMetal;if(pending){metal=pending.metal;host.selectMetal(metal);draft=blank(context());Object.assign(draft,pending,{months:context().rows.map(r=>r.month)});pending=null;review=null;}const base=sync(),a=active(base),stale=!!applied[metal]&&!a;return `<div class="planning-intro"><div><span class="eyebrow">EVIDENCE → ASSUMPTIONS → COMMERCIAL ACTION</span><h2>One reviewed scenario. One planning outlook.</h2><p>Model or run-rate baseline, explicit sensitivities and a visible decision record.</p></div><div><label for="planning-metal">Planning metal</label><select id="planning-metal">${['Zinc','Lead','Silver'].map(m=>`<option ${metal===m?'selected':''}>${m}</option>`).join('')}</select></div></div><div class="context-line">${esc(base.classification)} · ${base.rows[0].month}–${base.rows[2].month} · evidence available by ${base.asOf} · quantities in ${base.unit}</div><div class="planning-status"><strong>${a?'Scenario applied to this baseline':stale?'Previous application suspended':'Baseline active'}</strong><p>${a?esc(a.scenario.title)+' · reviewed by '+esc(a.reviewer):stale?'Inputs or horizon changed. Recalculate and review before applying again.':'Drafts do not change other dashboard pages.'} ${metal==='Silver'?'Silver uses an illustrative kg baseline here; no trained Silver model is available.':''}</p><div class="actions">${applied[metal]?'<button class="secondary" data-plan="remove">Remove applied scenario</button>':''}<button class="secondary" data-plan="export">Export decision record</button></div></div><div id="planning-message" role="status">${esc(message)}</div>${card('Current commercial outlook','Applied outlook or unchanged baseline · '+base.unit,table(['Month','Orders','Premium USD/'+base.unit,'Domestic reserve','Residual export'],outcome(base).rows.map(r=>[r.month,n(r.point),n(r.premium,2),n(r.domestic),n(r.export)]))+`<p class="mini">${a?'Reviewed sensitivities are applied.':'Reservations shown here follow demand plus buffer. The main dashboard keeps its customer-based allocation baseline until a scenario is reviewed and applied.'} Inspect the draft below to compare effects.</p>`)}${draftForm(base)}${review?`<section id="planning-review" class="planning-review"><div class="context-line"><strong>3 · Review before applying</strong> · changes below remain a draft until applied</div>${impact(review.result)}<label class="planning-check"><input type="checkbox" id="planning-confirm"> I reviewed the source, exposure, assumptions and baseline. This is a conditional planning scenario.</label><div class="actions"><button data-plan="apply">Apply reviewed scenario</button><button class="secondary" data-plan="discard">Discard review</button></div><p class="mini">Application is a local session annotation, not authenticated enterprise approval. A new application replaces this metal’s previous scenario.</p></section>`:a?impact(outcome(base)):''}${card('Decision lineage and implementation status','Transparent inputs and traceable calculations',`<ol class="event-logic"><li>Evidence: dated public report or a supplied structured record; no automated news verification.</li><li>Baseline: ${esc(base.classification)}. ${metal==='Silver'?'Illustrative Silver orders, price and cargo in kg.':'The same monthly baseline used by the executive dashboard, including candidate ML forecasts when enabled.'}</li><li>Transmission: order sensitivity × exposure × monthly weight. Premium, FX, freight and duty use their separate sensitivities.</li><li>Decision: preserve bookings, reserve domestic requirements and buffer, show remaining exports and capacity exceptions.</li><li>Review: compare against baseline, apply one scenario, export the record; changes to the baseline suspend application.</li></ol><details><summary>Inspect baseline and audit trail</summary><pre class="planning-json">${esc(JSON.stringify({baseline:base,sessionAudit:audit},null,2))}</pre></details><p class="mini">ERP/CRM, carrier milestones, Bloomberg/other licensed feeds, live LLM intake, role-based approvals and a persistent audit database are not connected. This session does not predict wars or provide calibrated 90% forecast intervals. Refresh clears drafts and records; export to retain your review.</p><div class="actions"><button class="secondary" data-plan="template">Download scenario JSON template</button><label class="upload-label" for="planning-import">Import scenario JSON · maximum 100 KB</label><input id="planning-import" type="file" accept="application/json,.json"></div><p class="mini">An imported record enters as an unreviewed draft. Import validates the schema and publication cutoff; it does not authenticate the source.</p>`)}`;}
function capture(form){const data=new FormData(form),v={...draft,changes:{},profile:[0,1,2].map(i=>Number(data.get('weight'+i)))};['title','source','url','published','geography','rationale','reviewer','cargoOrigin'].forEach(k=>v[k]=String(data.get(k)||''));v.exposure=Number(data.get('exposure'));Object.keys(E.defaults()).forEach(k=>v.changes[k]=Number(data.get(k)));return v;}
function refresh(){host.refresh();}
function save(name,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function snapshot(){if(!host)return {sessionAudit:audit};const ctx=context(),a=active(ctx);return {version:1,exportedAt:new Date().toISOString(),baseline:ctx,applied:a||null,suspended:!a?applied[metal]||null:null,draft,review:review||null,result:outcome(ctx),sessionAudit:audit,limitations:'Session only; no authenticated approval, live event prediction or calibrated intervals.'};}
document.addEventListener('submit',e=>{if(e.target.id!=='planning-form')return;e.preventDefault();if(!e.target.reportValidity())return;try{draft=capture(e.target);if(!draft.reviewer.trim())throw Error('Enter a reviewer name.');const ctx=context(),scenario=E.validate(draft,ctx);review={scenario,reviewer:draft.reviewer.trim(),fingerprint:E.fingerprint(ctx),draftKey:JSON.stringify(draft),result:E.calculate(ctx,scenario)};log('Calculated draft',{title:scenario.title});message='Review ready. Other pages are unchanged until you apply it.';refresh();document.getElementById('planning-review').scrollIntoView({block:'start'});}catch(err){message=err.message;document.getElementById('planning-message').textContent=message;}});
document.addEventListener('input',e=>{const form=e.target.closest('#planning-form');if(form)draft=capture(form);if(form&&review){review=null;document.getElementById('planning-review')?.remove();document.getElementById('planning-message').textContent='Draft edited. Calculate again before applying.';}});
document.addEventListener('change',async e=>{if(e.target.id==='planning-metal'){metal=e.target.value;host.selectMetal(metal);draft=null;review=null;message='';refresh();}if(e.target.id==='planning-import'){try{const file=e.target.files[0];if(!file)return;if(file.size>100000)throw Error('Scenario file exceeds 100 KB.');const raw=JSON.parse(await file.text()),ctx=context();draft={...E.validate(raw,ctx),reviewer:''};review=null;log('Imported unreviewed draft',{title:draft.title});message='Imported as an unreviewed draft. Inspect the source and assumptions.';refresh();}catch(err){document.getElementById('planning-message').textContent=err.message;}}});
document.addEventListener('click',e=>{const action=e.target.closest('[data-plan]')?.dataset.plan;if(!action)return;try{if(action==='case'){const id=document.getElementById('plan-case').value,c=D.cases.find(c=>c.id===id&&c.metals.includes(metal)&&c.published<=context().asOf);if(!c)throw Error('Choose an eligible evidence case.');draft=blank(context());Object.assign(draft,{title:c.title,source:c.source,url:c.url,published:c.published,geography:c.inputs,rationale:'Illustrative preset for '+c.title+'. '+c.limit,changes:{...E.defaults(),...(root.HZLGeopolitics?.events.some(e=>e.id===c.id)?root.HZLGeopolitics.preset(c,metal):c.preset),dutyDelta:c.preset.duty||0}});delete draft.changes.duty;delete draft.changes.deferral;review=null;message='Historical case loaded with hypothetical sensitivities. Check exposure and monthly weights.';refresh();}if(action==='apply'){if(!review)throw Error('Calculate and review the draft first.');if(!document.getElementById('planning-confirm')?.checked)throw Error('Confirm your review before applying.');if(review.fingerprint!==E.fingerprint(context()))throw Error('Baseline changed. Recalculate and review.');const sourceCase=D.cases.find(c=>c.title===review.scenario.title&&c.url===review.scenario.url&&c.published===review.scenario.published),record={scenario:review.scenario,reviewer:review.reviewer,reviewedAt:new Date().toISOString(),fingerprint:review.fingerprint,baseline:structuredClone(context()),publicEvidence:sourceCase?{id:sourceCase.id,fact:sourceCase.fact,period:sourceCase.period,source:sourceCase.source,url:sourceCase.url,published:sourceCase.published,limit:sourceCase.limit}:null};applied[metal]=record;log('Applied reviewed scenario',{title:record.scenario.title,reviewer:record.reviewer});review=null;message=metal==='Silver'?'Applied to the Silver planning workspace. The main commercial dashboard currently covers Zinc and Lead.':'Applied. The executive outlook for this metal now uses the reviewed scenario.';refresh();}if(action==='remove'){delete applied[metal];review=null;log('Removed applied scenario',{});message='Baseline restored across the dashboard.';refresh();}if(action==='discard'){review=null;message='Review discarded; the applied outlook is unchanged.';refresh();}if(action==='export')save('HZL-connected-decision-record.json',snapshot());if(action==='template')save('HZL-scenario-template.json',blank(context()));}catch(err){message=err.message;document.getElementById('planning-message').textContent=message;}});
root.HZLPlanning={render,active,outcome,banner,snapshot,queueFromCase(m,c,changes){pending={...blank(host?host.context(m):{metal:m,asOf:'2026-10-23',rows:[{month:'2026-11'},{month:'2026-12'},{month:'2027-01'}]}),metal:m,title:c.title,source:c.source,url:c.url,published:c.published,geography:c.inputs,rationale:'Historical case translated into hypothetical assumptions. The lab-only manual arrival deferral is excluded. The connected calculation uses its shared baseline and registered cargo dates. '+c.limit,changes:{demandShock:changes.demandShock,priceShock:changes.priceShock,premiumShift:changes.premiumShift,freightShift:changes.freightShift,fxShock:changes.fxShock,dutyDelta:changes.duty,delay:changes.delay}};if(location.hash==='#planning')root.dispatchEvent(new Event('hashchange'));else location.hash='planning';}};
})(window);
